import{_ as i,C as s,o as d,c as l,j as a,a as c,E as o,ag as r}from"./chunks/framework.DMVuHR7L.js";const v=JSON.parse('{"title":"Logcat","description":"","frontmatter":{},"headers":[],"relativePath":"features/logcat.md","filePath":"features/logcat.md","lastUpdated":1778759304000}'),n={name:"features/logcat.md"};function h(p,e,g,u,m,f){const t=s("ThemeImage");return d(),l("div",null,[e[0]||(e[0]=a("h1",{id:"logcat",tabindex:"-1"},[c("Logcat "),a("a",{class:"header-anchor",href:"#logcat","aria-label":'Permalink to "Logcat"'},"​")],-1)),e[1]||(e[1]=a("p",null,"The Logcat widget streams the device's system log live. Multiple Logcat tiles can co-exist on the same device with independent filter and pin state, so you can keep a global view alongside a tag-scoped one.",-1)),o(t,{"src-dark":"/img/features/logcat-default.png","src-light":"/img/features/logcat-default-light.png",alt:"Logcat tile"}),e[2]||(e[2]=r('<h2 id="filter-chips" tabindex="-1">Filter chips <a class="header-anchor" href="#filter-chips" aria-label="Permalink to &quot;Filter chips&quot;">​</a></h2><p>Focus the filter bar (or press <code>/</code>) to bring up the autocomplete. All five filter types appear as discoverable starters:</p><table tabindex="0"><thead><tr><th>Prefix</th><th>Matches</th><th>Example</th></tr></thead><tbody><tr><td><code>process:</code></td><td>Package name (substring)</td><td><code>process:com.example</code></td></tr><tr><td><code>tag:</code></td><td>Logcat tag (substring)</td><td><code>tag:ActivityManager</code></td></tr><tr><td><code>pid:</code></td><td>Process or thread id (exact)</td><td><code>pid:1234</code></td></tr><tr><td><code>level:</code></td><td>Log level letter</td><td><code>level:E</code></td></tr><tr><td><em>(no prefix)</em></td><td>Search across message + tag + package</td><td><code>OutOfMemoryError</code></td></tr></tbody></table><p><code>Tab</code> accepts the highlighted suggestion, <code>Enter</code> commits the chip, <code>Backspace</code> on an empty input removes the previous chip. Adding the first chip auto-enables <em>show only matches</em>; clear all chips to see everything again.</p>',4)),o(t,{"src-dark":"/img/features/logcat-chips.png","src-light":"/img/features/logcat-chips-light.png",alt:"Filter chips"}),e[3]||(e[3]=r('<h2 id="find-next-match" tabindex="-1">Find-next-match <a class="header-anchor" href="#find-next-match" aria-label="Permalink to &quot;Find-next-match&quot;">​</a></h2><p>Click a filter chip to activate it for navigation — the first matching row is highlighted (the <em>active match</em>) and the up/down buttons next to the chip step through the rest. <code>⌘G</code> / <code>Ctrl+G</code> advances; <code>⇧⌘G</code> / <code>Ctrl+Shift+G</code> goes backward. Pressing <code>⌘G</code> without an active chip falls back to activating the rightmost chip, so you can chain <em>add filter → ⌘G</em> without clicking.</p><p>Stepping with <code>⌘G</code> only scrolls when it has to: if the next match is already on screen the viewport stays put and the highlight moves to it; if the match is off-screen the row is centred.</p><p>Clicking a log row selects it the same way — the row gets the active-match highlight. From there, <code>⌘G</code> resumes navigation in the active filter&#39;s match list. Toggling <em>show only matches</em> keeps the active row at the same on-screen position; rows scrolled off the top or bottom snap to the nearest edge of the viewport.</p><h2 id="level-pills" tabindex="-1">Level pills <a class="header-anchor" href="#level-pills" aria-label="Permalink to &quot;Level pills&quot;">​</a></h2><p>The five level pills (V/D/I/W/E) above the log show the live rate per level.</p><ul><li><strong>Click</strong> a pill to toggle that level on / off.</li><li><strong>Double-click</strong> to <em>solo</em> — turns every other level off.</li><li>A struck-through pill means the level is hidden.</li></ul><h2 id="pinned-rows" tabindex="-1">Pinned rows <a class="header-anchor" href="#pinned-rows" aria-label="Permalink to &quot;Pinned rows&quot;">​</a></h2><p>Hover a row and click the pin icon to stick it to the top of the log. Pinned rows survive scrolling and stay visible even when their original position scrolls off-screen. Click the pin again to unpin.</p>',9)),o(t,{"src-dark":"/img/features/logcat-pinned.png","src-light":"/img/features/logcat-pinned-light.png",alt:"Pinned rows"}),e[4]||(e[4]=r('<h2 id="crash-collapse" tabindex="-1">Crash collapse <a class="header-anchor" href="#crash-collapse" aria-label="Permalink to &quot;Crash collapse&quot;">​</a></h2><p>Stack traces fold under their first line by default. Click <em>Show stack trace</em> on a folded row to expand it. The collapse heuristic recognises both Java exceptions and ANR / native traces.</p><h2 id="heatmap-gutter" tabindex="-1">Heatmap gutter <a class="header-anchor" href="#heatmap-gutter" aria-label="Permalink to &quot;Heatmap gutter&quot;">​</a></h2><p>A 60-cell bar on the left of the log area buckets the last minute of activity into one cell per second. Cell brightness scales with rate; click any second to scroll the log to that point in time.</p><h2 id="wrap-mode" tabindex="-1">Wrap mode <a class="header-anchor" href="#wrap-mode" aria-label="Permalink to &quot;Wrap mode&quot;">​</a></h2><p>Off by default — long messages scroll horizontally so timestamps stay aligned. Toggle <strong>wrap</strong> in the toolbar (or via the per-widget settings modal) to wrap long messages within the row.</p><h2 id="pause-and-clear" tabindex="-1">Pause and clear <a class="header-anchor" href="#pause-and-clear" aria-label="Permalink to &quot;Pause and clear&quot;">​</a></h2><ul><li><code>Space</code> toggles pause. While paused, incoming entries queue up and flush in batch when you resume.</li><li><code>⌘K</code> / <code>Ctrl+K</code> clears the visible buffer (the upstream stream keeps going).</li></ul><h2 id="per-widget-settings" tabindex="-1">Per-widget settings <a class="header-anchor" href="#per-widget-settings" aria-label="Permalink to &quot;Per-widget settings&quot;">​</a></h2><p>The cog in the tile header opens a settings modal for <strong>this</strong> Logcat instance. From there you can flip wrap, change row density, edit the default level mask, or rename the tile. Changes persist per-tile.</p><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h2><p>Shortcuts only fire while the widget owns focus, so two Logcat tiles never toggle each other.</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Space</code></td><td>Pause / resume the live stream</td></tr><tr><td><code>/</code></td><td>Focus the filter input</td></tr><tr><td><code>⌘F</code> / <code>Ctrl+F</code></td><td>Focus the filter input (same as <code>/</code>; cross-widget fallback when no widget is focused)</td></tr><tr><td><code>⌘G</code> / <code>Ctrl+G</code></td><td>Next match for the active chip (or activate the rightmost chip)</td></tr><tr><td><code>⇧⌘G</code> / <code>Ctrl+Shift+G</code></td><td>Previous match for the active chip</td></tr><tr><td><code>⌘K</code> / <code>Ctrl+K</code></td><td>Clear the log buffer</td></tr><tr><td><code>?</code></td><td>Open the in-app shortcut reference</td></tr><tr><td><code>Esc</code></td><td>Close any open overlay</td></tr></tbody></table><p>Press <code>?</code> in-app for the always-current list.</p>',14))])}const w=i(n,[["render",h]]);export{v as __pageData,w as default};
